const f = $input.first().json;
const n = Math.max(1, Math.min(200, parseInt(f['How many videos?'] || '10', 10) || 10));
const langs = { 'English + Telugu + Hindi': 'en te hi', 'English + Telugu': 'en te', 'English + Hindi': 'en hi', 'English': 'en', 'Telugu': 'te', 'Hindi': 'hi' }[f['Language']] || 'en te hi';
const style = { 'Weekend home': 'weekend_home' }[f['Style']] || 'weekend_home';
const analyse = f['New clips added to Drive since last time?'] === 'Yes' ? 'yes' : 'no';
const jobs = $env.CE_JOBS_DIR;   // office PC: n8n runs in Docker, the host's watcher (start_form.ps1) runs the job
if (jobs) {
  const fs = require('fs');
  const id = new Date().toISOString().replace(/[:.]/g, '-');
  fs.writeFileSync(`${jobs}/${id}.json`, JSON.stringify({ n, langs, style, analyse }));
  return [{ json: { cmd: `echo queued ${id}` } }];
}
return [{ json: { cmd: `bash -lc 'nohup /workspace/make_videos.sh ${n} "${langs}" ${style} ${analyse} > /dev/null 2>&1 &'` } }];
